let cloudflareToken = "", cloudflareAccountId = "", cloudflareAccountName = "", cloudflareProjects = [];
function readGitHubSessionToken(){try{return sessionStorage.getItem("miniai.githubToken")||""}catch{return ""}}
function writeGitHubSessionToken(value){try{if(value)sessionStorage.setItem("miniai.githubToken",value);else sessionStorage.removeItem("miniai.githubToken")}catch{}}
let githubToken = readGitHubSessionToken(), githubConnected = Boolean(githubToken), githubOwner = "dallasaristarchos-hue", githubRepo = "MiniAI", githubBranch = "main";
