function uid(){return globalThis.crypto?.randomUUID?.() || `chat-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function loadChats(){try{const value=JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]");return Array.isArray(value)?value.filter(c=>c&&c.id&&Array.isArray(c.messages)):[]}catch{return []}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(chats));if(activeId)localStorage.setItem(ACTIVE_KEY,activeId)}catch{showToast("Storage is full. Export an older chat to keep it safe.")}}
function currentChat(){return chats.find(c=>c.id===activeId)}
function makeChat(mode="general"){const chat={id:uid(),title:mode==="coding"?"New coding chat":"New conversation",mode,updatedAt:Date.now(),messages:[]};chats.unshift(chat);activeId=chat.id;save();renderAll();input.focus();closeSidebar();}
function showToast(message){const el=$("#toast");el.textContent=message;el.classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("visible"),2300)}
function accountHeaders(extra={}){return {...extra,...(accountToken?{Authorization:`Bearer ${accountToken}`}:{})}}
async function accountRequest(path,options={}){const response=await fetch(`${API_URL.replace("/api/chat","")}${path}`,{...options,headers:accountHeaders({Accept:"application/json",...(options.headers||{})})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"Account request failed.");return data}
async function cloudflareCall(action,extra={},tokenOverride=""){if(!accountToken||!currentAccount)throw new Error("Sign in to your MiniAI account first.");const token=tokenOverride||cloudflareToken;if(!token)throw new Error("Connect your Cloudflare API token first.");const response=await fetch(API_URL.replace("/api/chat","/api/cloudflare"),{method:"POST",cache:"no-store",headers:accountHeaders({"Content-Type":"application/json",Accept:"application/json"}),body:JSON.stringify({action,token,...extra})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Cloudflare request failed (${response.status}).`);return data}
async function githubConnectRequest(token,owner,repo,branch){const response=await fetch(API_URL.replace("/api/chat","/api/github"),{method:"POST",cache:"no-store",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({token,owner,repo,branch})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`GitHub connection failed (${response.status}).`);return data}
function setGitHubStatus(message,error=false){const el=$("#githubStatus");if(el){el.textContent=message;el.classList.toggle("error",error)}}
async function connectGitHub(){const token=$("#githubApiToken").value.trim(),owner=$("#githubOwner").value.trim(),repo=$("#githubRepo").value.trim(),branch=$("#githubBranch").value.trim()||"main",button=$("#githubConnect");button.disabled=true;setGitHubStatus(token?"Verifying GitHub access and repository write permissions…":"Checking public repository access (read-only)…");try{const data=await githubConnectRequest(token,owner,repo,branch);githubToken=token;writeGitHubSessionToken(token);githubConnected=true;githubOwner=owner;githubRepo=repo;githubBranch=data.branch||branch;$("#githubApiToken").value="";$("#githubDisconnect").disabled=false;setGitHubStatus(`${data.writePermission==="read-only"?"Public repository · read-only":"Connected as "+data.login} · ${data.repository} · ${data.fileCount} files · branch ${githubBranch}.`)}catch(error){githubToken="";githubConnected=false;setGitHubStatus(error.message,true)}finally{button.disabled=false}}
function disconnectGitHub(){githubToken="";writeGitHubSessionToken("");githubConnected=false;$("#githubApiToken").value="";$("#githubDisconnect").disabled=true;setGitHubStatus("Disconnected. The GitHub token was cleared from this tab's memory.")}
function setCloudflareStatus(message,error=false){const el=$("#cfStatus");if(el){el.textContent=message;el.classList.toggle("error",error)}}
function renderCloudflareDashboard(data){const workers=Array.isArray(data.workers)?data.workers:[],pages=Array.isArray(data.pages)?data.pages:[],accountId=cloudflareAccountId;$("#cfDashboard").hidden=false;$("#cfWorkerCount").textContent=workers.length;$("#cfPagesCount").textContent=pages.length;$("#cfResourceSummary").textContent=`${workers.length} Workers · ${pages.length} Pages projects`;$("#cfOpenDashboard").href=`https://dash.cloudflare.com/${accountId}/workers-and-pages`;const workerList=$("#cfWorkerList");workerList.innerHTML=workers.length?workers.map(item=>{const name=String(item.id||item.name||"Unnamed Worker"),date=item.modified_on||item.created_on||"";const href=`https://dash.cloudflare.com/${accountId}/workers/services/view/${encodeURIComponent(name)}/production`;return `<article class="cf-resource"><div class="cf-resource-copy"><strong>${escapeHTML(name)}</strong><small>${date?`Updated ${escapeHTML(new Date(date).toLocaleDateString())}`:"Worker script"}</small></div><a href="${href}" target="_blank" rel="noopener noreferrer">Manage <span aria-hidden="true">↗</span></a></article>`}).join(""):'<p class="cf-empty">No Workers were returned for this account.</p>';const pagesList=$("#cfPagesList");pagesList.innerHTML=pages.length?pages.map(item=>{const name=String(item.name||"Unnamed project"),branch=item.production_branch||"";const href=`https://dash.cloudflare.com/${accountId}/pages/view/${encodeURIComponent(name)}`;return `<article class="cf-resource"><div class="cf-resource-copy"><strong>${escapeHTML(name)}</strong><small>${branch?`Production branch: ${escapeHTML(branch)}`:"Cloudflare Pages project"}</small></div><a href="${href}" target="_blank" rel="noopener noreferrer">Manage <span aria-hidden="true">↗</span></a></article>`}).join(""):'<p class="cf-empty">No Pages projects were returned for this account.</p>';const select=$("#cfProjectSelect"),previous=select.value;select.replaceChildren(new Option("Choose a Pages project",""));pages.forEach(item=>select.add(new Option(item.name,item.name)));if(pages.some(item=>item.name===previous))select.value=previous;else $("#cfDeploymentList").innerHTML='<p class="cf-empty">Choose a project to view deployment history.</p>';$("#cfAccountLabel").textContent=cloudflareAccountName||data.accountName||`Cloudflare account · ${accountId.slice(0,8)}…`}
async function connectCloudflare(){const token=$("#cfApiToken").value.trim(),button=$("#cfConnect");if(!token){setCloudflareStatus("Paste a Cloudflare API token first.",true);return}button.disabled=true;setCloudflareStatus("Verifying your Cloudflare token…");try{const accountId=$("#cfAccountId").value.trim();const data=await cloudflareCall("connect",{accountId},token);if(!data.connected)throw new Error("Cloudflare did not accept this token.");cloudflareToken=token;$("#cfApiToken").value="";$("#cfDisconnect").disabled=false;$("#cfRefresh").disabled=false;const accounts=Array.isArray(data.accounts)?data.accounts:[];const picker=$("#cfAccountSelect"),pickerWrap=$("#cfAccountPickerWrap");picker.replaceChildren(new Option("Choose an account",""));accounts.forEach(item=>picker.add(new Option(`${item.name||"Cloudflare account"} · ${String(item.id||"").slice(0,8)}…`,item.id)));pickerWrap.hidden=accounts.length<2;const matched=accounts.find(a=>a.id===($("#cfAccountId").value.trim()))||(accounts.length===1?accounts[0]:null);if(matched){$("#cfAccountId").value=matched.id;picker.value=matched.id;cloudflareAccountId=matched.id;cloudflareAccountName=matched.name||""}else{cloudflareAccountId=$("#cfAccountId").value.trim();cloudflareAccountName="";if(cloudflareAccountId)picker.value=cloudflareAccountId;}if(!cloudflareAccountId){setCloudflareStatus(data.accountsWarning||"Token verified. Enter your 32-character Cloudflare account ID to load resources.");return}setCloudflareStatus("Cloudflare connected. Loading your resources…");await refreshCloudflareDashboard()}catch(error){cloudflareToken="";setCloudflareStatus(error.message,true)}finally{button.disabled=false}}
async function refreshCloudflareDashboard(){const accountId=$("#cfAccountId").value.trim();if(!/^[a-f0-9]{32}$/i.test(accountId)){setCloudflareStatus("Enter a valid 32-character Cloudflare account ID.",true);return}cloudflareAccountId=accountId;const button=$("#cfRefresh");if(button)button.disabled=true;setCloudflareStatus("Loading Workers and Pages…");try{const data=await cloudflareCall("dashboard",{accountId});cloudflareProjects=Array.isArray(data.pages)?data.pages:[];renderCloudflareDashboard(data);setCloudflareStatus("Connected · Cloudflare resources are up to date.")}catch(error){setCloudflareStatus(error.message,true)}finally{if(button)button.disabled=!cloudflareToken}}
async function loadCloudflareDeployments(){const project=$("#cfProjectSelect").value;if(!project)return;const list=$("#cfDeploymentList");list.innerHTML='<p class="cf-empty">Loading deployment history…</p>';try{const data=await cloudflareCall("deployments",{accountId:cloudflareAccountId,projectName:project});const items=Array.isArray(data.deployments)?data.deployments:[];list.innerHTML=items.length?items.map(item=>{const id=String(item.id||""),status=item.latest_stage?.status||"unknown",env=item.environment||"preview",date=item.created_on?new Date(item.created_on).toLocaleString():"Date unavailable",branch=item.deployment_trigger?.metadata?.branch||"",canRollback=env==="production"&&status==="success",canRetry=status==="failure"||status==="canceled";return `<article class="cf-resource cf-deployment"><div class="cf-resource-copy"><strong>${escapeHTML(env)} · ${escapeHTML(status)}</strong><small>${escapeHTML(date)}${branch?` · ${escapeHTML(branch)}`:""}</small><small>${escapeHTML(String(item.short_id||id).slice(0,18))}</small></div><div class="cf-deployment-actions">${item.url?`<a href="${escapeHTML(item.url)}" target="_blank" rel="noopener noreferrer">Preview ↗</a>`:""}${canRetry?`<button type="button" data-cf-action="retry" data-cf-project="${escapeHTML(project)}" data-cf-deployment="${escapeHTML(id)}">Retry</button>`:""}${canRollback?`<button type="button" data-cf-action="rollback" data-cf-project="${escapeHTML(project)}" data-cf-deployment="${escapeHTML(id)}">Rollback</button>`:""}</div></article>`}).join(""):'<p class="cf-empty">No deployments found for this project.</p>';list.querySelectorAll("[data-cf-action]").forEach(button=>button.addEventListener("click",()=>runCloudflareDeploymentAction(button.dataset.cfAction,button.dataset.cfProject,button.dataset.cfDeployment,button)));}catch(error){list.innerHTML=`<p class="cf-empty cf-error">${escapeHTML(error.message)}</p>`}}
async function runCloudflareDeploymentAction(action,project,id,button){const rollback=action==="rollback",message=rollback?"Roll back this Pages project to the selected successful production deployment? This changes the live production site.":"Retry this failed Pages deployment? Cloudflare will start a new build.";if(!window.confirm(message))return;button.disabled=true;setCloudflareStatus(rollback?"Rolling back production…":"Retrying deployment…");try{await cloudflareCall(action,{accountId:cloudflareAccountId,projectName:project,deploymentId:id});setCloudflareStatus(rollback?"Rollback request completed.":"Deployment retry requested.");await loadCloudflareDeployments();}catch(error){setCloudflareStatus(error.message,true);button.disabled=false}}
function disconnectCloudflare(){cloudflareToken="";cloudflareAccountId="";cloudflareAccountName="";cloudflareProjects=[];$("#cfApiToken").value="";$("#cfAccountId").value="";$("#cfAccountPickerWrap").hidden=true;$("#cfAccountSelect").replaceChildren(new Option("Choose an account",""));$("#cfDashboard").hidden=true;$("#cfDisconnect").disabled=true;$("#cfRefresh").disabled=true;$("#cfWorkerList").innerHTML='<p class="cf-empty">Connect to load Workers.</p>';$("#cfPagesList").innerHTML='<p class="cf-empty">Connect to load Pages projects.</p>';$("#cfDeploymentList").innerHTML='<p class="cf-empty">Choose a project to view deployment history.</p>';setCloudflareStatus("Disconnected. Your Cloudflare token was cleared from this tab.")}

function paintRatingStars(){document.querySelectorAll("[data-rating]").forEach(button=>{const value=Number(button.dataset.rating);button.classList.toggle("selected",value<=selectedRating);button.setAttribute("aria-pressed",String(value===selectedRating));button.disabled=accountRated||!currentAccount})}
async function loadRatingSummary(){const summary=$("#ratingSummary");if(!summary)return;try{const response=await fetch(RATING_API_URL,{method:"GET",cache:"no-store",headers:{Accept:"application/json"}});if(!response.ok)throw new Error("Unavailable");const data=await response.json();summary.textContent=data.count?`${Number(data.average).toFixed(1)} / 5 · ${Number(data.count).toLocaleString()} ${data.count===1?"rating":"ratings"}`:"Be the first to rate MiniAI."}catch{summary.textContent="Community rating is temporarily unavailable."}}
function showAccountState(){const signedOut=$("#accountSignedOut"),signedIn=$("#accountSignedIn"),controls=$("#ratingControls"),status=$("#ratingStatus");if(signedOut)signedOut.hidden=Boolean(currentAccount);if(signedIn)signedIn.hidden=!currentAccount;if(controls)controls.hidden=!currentAccount||accountRated;if(currentAccount){const name=currentAccount.displayName||currentAccount.username;$("#accountDisplayName").textContent=name;$("#accountAvatar").textContent=name.slice(0,1).toUpperCase();if(status)status.textContent=accountRated?"This account has already rated MiniAI. Each account can rate only once.":"You're signed in. You can submit one rating from this account."}else if(status)status.textContent="Sign in or create an account to submit one rating. Ratings cannot be changed after submission.";paintRatingStars();const submit=$("#submitRating");if(submit)submit.disabled=!currentAccount||accountRated||!selectedRating}
async function refreshAccountRating(){accountRated=false;selectedRating=0;if(!currentAccount){showAccountState();return}try{const data=await accountRequest("/api/ratings/me");accountRated=Boolean(data.rated);selectedRating=accountRated?Number(data.rating):0}catch(error){if(error.message.includes("Sign in")){accountToken="";currentAccount=null;disconnectCloudflare();localStorage.removeItem(ACCOUNT_TOKEN_KEY)}else showToast(error.message)}showAccountState()}
async function completeAccountAuth(mode){if(authBusy)return;const name=$("#accountName").value.trim(),password=$("#accountPassword").value,status=$("#accountStatus"),buttons=[$("#createAccount"),$("#signInAccount")];if(!name||!password){status.textContent="Enter an account name and password.";return}authBusy=true;buttons.forEach(button=>button.disabled=true);status.textContent=mode==="register"?"Creating your account…":"Signing in…";try{const data=await accountRequest(`/api/auth/${mode}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:name,password})});accountToken=data.token;localStorage.setItem(ACCOUNT_TOKEN_KEY,accountToken);currentAccount=data.account;$("#accountPassword").value="";status.textContent=`Welcome, ${currentAccount.displayName}!`;await refreshAccountRating()}catch(error){status.textContent=error.message}finally{authBusy=false;buttons.forEach(button=>button.disabled=false)}}
function bindRatingUI(){const submit=$("#submitRating"),feedback=$("#ratingFeedback"),status=$("#ratingStatus");$("#createAccount")?.addEventListener("click",()=>completeAccountAuth("register"));$("#signInAccount")?.addEventListener("click",()=>completeAccountAuth("login"));$("#signOutAccount")?.addEventListener("click",async()=>{try{await accountRequest("/api/auth/logout",{method:"POST"})}catch{}accountToken="";currentAccount=null;accountRated=false;selectedRating=0;disconnectCloudflare();localStorage.removeItem(ACCOUNT_TOKEN_KEY);showAccountState()});$("#deleteAccount")?.addEventListener("click",async()=>{if(!currentAccount)return;if(!window.confirm("Delete your MiniAI account and its rating? This cannot be undone."))return;const button=$("#deleteAccount");button.disabled=true;try{await accountRequest("/api/auth/me",{method:"DELETE"});accountToken="";currentAccount=null;accountRated=false;selectedRating=0;disconnectCloudflare();localStorage.removeItem(ACCOUNT_TOKEN_KEY);showAccountState();if(status)status.textContent="Your account and associated rating have been deleted.";await loadRatingSummary()}catch(error){if(status)status.textContent=error.message}finally{button.disabled=false}});document.querySelectorAll("[data-rating]").forEach(button=>button.addEventListener("click",()=>{if(!currentAccount||accountRated)return;selectedRating=Number(button.dataset.rating);paintRatingStars();if(submit)submit.disabled=false;if(status)status.textContent=`You selected ${selectedRating} out of 5 stars.`}));submit?.addEventListener("click",async()=>{if(!currentAccount||accountRated){if(status)status.textContent="Sign in with an account that has not rated yet.";return}if(!selectedRating){if(status)status.textContent="Choose a star rating first.";return}submit.disabled=true;if(status)status.textContent="Sending your one-time rating…";try{const data=await accountRequest("/api/ratings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({rating:selectedRating,feedback:feedback?.value.trim().slice(0,500)||""})});accountRated=true;if(feedback)feedback.value="";if(status)status.textContent="Thanks! This account's one rating has been saved and cannot be changed.";showAccountState();await loadRatingSummary()}catch(error){if(status)status.textContent=error.message;await refreshAccountRating()}finally{submit.disabled=!currentAccount||accountRated||!selectedRating}});loadRatingSummary();(async()=>{if(accountToken){try{const data=await accountRequest("/api/auth/me");currentAccount=data.account;await refreshAccountRating()}catch{accountToken="";currentAccount=null;localStorage.removeItem(ACCOUNT_TOKEN_KEY);showAccountState()}}else showAccountState()})();}

function escapeHTML(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));}
function safeLink(url){try{const parsed=new URL(url);return ["https:","http:"].includes(parsed.protocol)?parsed.href:null}catch{return null}}
function inlineMarkdown(value){let out=escapeHTML(value);out=out.replace(/`([^`]+)`/g,"<code>$1</code>");out=out.replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g,"<em>$1</em>");out=out.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(all,label,url)=>{const safe=safeLink(url);return safe?`<a href="${escapeHTML(safe)}" target="_blank" rel="noopener noreferrer">${label}</a>`:label});out=out.replace(/(^|\s)(https?:\/\/[^\s<]+)/g,(all,space,url)=>{const clean=url.replace(/[.,!?;:]+$/g,"");const safe=safeLink(clean);return safe?`${space}<a href="${escapeHTML(safe)}" target="_blank" rel="noopener noreferrer">${escapeHTML(clean)}</a>${url.slice(clean.length)}`:all});return out}
function markdownHTML(text){const chunks=String(text).split(/```([\s\S]*?)```/g);return chunks.map((chunk,index)=>{if(index%2===1){const lines=chunk.replace(/^\n|\n$/g,"").split("\n");let lang="code";if(lines.length&&/^[a-zA-Z0-9_+-]{1,20}$/.test(lines[0].trim()))lang=lines.shift().trim();const code=lines.join("\n");return `<div class="code-wrap"><div class="code-head"><span>${escapeHTML(lang)}</span><button class="code-copy" type="button" data-action="copy-code">Copy code</button></div><pre>${escapeHTML(code)}</pre></div>`;}const lines=chunk.split("\n");let html="",listType=null;const closeList=()=>{if(listType){html+=`</${listType}>`;listType=null}};for(const line of lines){const trimmed=line.trim();const bullet=trimmed.match(/^[-*]\s+(.+)/),number=trimmed.match(/^\d+[.)]\s+(.+)/);if(bullet||number){const type=bullet?"ul":"ol";if(listType!==type){closeList();html+=`<${type}>`;listType=type}html+=`<li>${inlineMarkdown((bullet||number)[1])}</li>`;continue}closeList();if(!trimmed){html+="<br>";continue}const heading=trimmed.match(/^#{1,3}\s+(.+)/);if(heading){html+=`<p><strong>${inlineMarkdown(heading[1])}</strong></p>`;continue}if(trimmed.startsWith("> ")){html+=`<blockquote>${inlineMarkdown(trimmed.slice(2))}</blockquote>`;continue}html+=`<p>${inlineMarkdown(line)}</p>`;}closeList();return html;}).join("")}
function renderMessage(message){const row=document.createElement("article");row.className=`message ${message.role}`;row.__messageText=message.content;row.__failed=Boolean(message.failed);const avatar=document.createElement("div");avatar.className="avatar";avatar.textContent=message.role==="user"?"Y":(String(prefs.assistantName||"MiniAI").trim().charAt(0).toUpperCase()||"M");avatar.setAttribute("aria-hidden","true");const content=document.createElement("div");content.className="message-content";if(message.role!=="user"){const author=document.createElement("div");author.className="message-author";author.textContent=prefs.assistantName||"MiniAI";content.append(author)}const bubble=document.createElement("div");bubble.className="bubble";bubble.innerHTML=markdownHTML(message.content);content.append(bubble);const actions=document.createElement("div");actions.className="message-actions";const copy=document.createElement("button");copy.type="button";copy.dataset.action="copy-message";copy.textContent="Copy";actions.append(copy);if(message.role==="assistant"&&!message.failed){const report=document.createElement("button");report.type="button";report.dataset.action="report-message";report.textContent="Report";report.setAttribute("aria-label","Report this AI response");actions.append(report)}if(message.failed){const retry=document.createElement("button");retry.type="button";retry.dataset.action="retry";retry.textContent="Try again";actions.append(retry)}content.append(actions);row.append(avatar,content);return row;}
function renderHistory(){const list=$("#historyList"),query=$("#historySearch").value.trim().toLowerCase();list.replaceChildren();const visible=[...chats].sort((a,b)=>b.updatedAt-a.updatedAt).filter(c=>!query||c.title.toLowerCase().includes(query)||c.messages.some(m=>m.content.toLowerCase().includes(query)));if(!visible.length){const empty=document.createElement("div");empty.className="history-empty";empty.textContent=query?"No matching conversations.":"Your conversations will appear here.";list.append(empty);return}for(const chat of visible){const item=document.createElement("div");item.className=`history-item${chat.id===activeId?" active":""}${chat.mode==="coding"?" coding-history-item":""}`;item.tabIndex=0;item.setAttribute("role","button");item.setAttribute("aria-label",`Open ${chat.title}`);const icon=document.createElement("span");icon.className="history-icon";icon.textContent="◷";const title=document.createElement("span");title.className="history-title";title.textContent=chat.title;const del=document.createElement("button");del.className="history-delete";del.type="button";del.dataset.deleteChat=chat.id;del.setAttribute("aria-label",`Delete ${chat.title}`);del.textContent="×";if(chat.mode==="coding"){const tag=document.createElement("span");tag.className="history-code-tag";tag.textContent="CODE";item.append(icon,title,tag,del)}else item.append(icon,title,del);item.addEventListener("click",e=>{if(e.target.closest("[data-delete-chat]"))return;activeId=chat.id;save();renderAll();closeSidebar()});item.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();activeId=chat.id;save();renderAll();closeSidebar()}});list.append(item)}}
let conversationPinnedToBottom=true;
function scrollConversationToBottom(force=false){if(!force&&!conversationPinnedToBottom)return;conversation.scrollTop=conversation.scrollHeight;}
conversation.addEventListener("scroll",()=>{const gap=conversation.scrollHeight-conversation.scrollTop-conversation.clientHeight;conversationPinnedToBottom=gap<90;},{passive:true});
function renderConversation(){const chat=currentChat();messagesEl.replaceChildren();const welcome=$("#welcome");const hasMessages=Boolean(chat?.messages.length);welcome.hidden=hasMessages;if(chat)chat.messages.forEach(message=>messagesEl.append(renderMessage(message)));conversationPinnedToBottom=true;scrollConversationToBottom(true);}
function renderAll(){renderHistory();renderConversation();const chat=currentChat();const badge=$("#chatModeBadge");if(badge)badge.hidden=chat?.mode!=="coding";document.body.classList.toggle("coding-chat-active",chat?.mode==="coding")}
function titleFrom(text){const clean=text.replace(/\s+/g," ").trim();return clean.length>34?clean.slice(0,34).trim()+"…":clean||"New conversation"}
function setBusy(value){busy=value;sendButton.disabled=value;sendButton.innerHTML=value?"<span>…</span>":"<span>↑</span>";sendButton.setAttribute("aria-label",value?"Waiting for MiniAI":"Send message")}
function appendMessage(role,content,extra={}){const chat=currentChat();if(!chat)return null;const message={role,content,createdAt:Date.now(),...extra};chat.messages.push(message);chat.updatedAt=Date.now();if(role==="user"&&chat.title==="New conversation")chat.title=titleFrom(content);save();renderAll();return message}
function showTyping(status="Thinking through your question…"){const row=document.createElement("article");row.className="message";row.id="typingIndicator";row.innerHTML=`<div class="avatar" aria-hidden="true">${escapeHTML((prefs.assistantName||"MiniAI").trim().charAt(0).toUpperCase()||"M")}</div><div class="message-content"><div class="message-author">${escapeHTML(prefs.assistantName||"MiniAI")}</div><div class="bubble"><span class="typing" aria-label="${escapeHTML(prefs.assistantName||"MiniAI")} is working"><i></i><i></i><i></i></span><span class="work-status" style="display:block;margin-top:7px;color:#c7a2f3;font-size:11px;letter-spacing:.2px">${escapeHTML(status)}</span></div></div>`;messagesEl.append(row);scrollConversationToBottom()}
function needsWebResearch(text){return /\b(latest|today|current|currently|202[5-9]|price|prices|cost|buy|budget|best|compare|review|release|news|weather|available|availability|specs|specifications|benchmark|deal|where can i|search|research|recommend|recommendation|pc build|gaming pc|gpu|cpu|motherboard|laptop|phone|market|version)\b/i.test(text)}
function cleanHistory(){return (currentChat()?.messages||[]).filter(m=>!m.failed&&["user","assistant"].includes(m.role)).slice(-12).map(m=>({role:m.role,content:m.content}))}
function fileExtension(name){return (String(name).split(".").pop()||"").toLowerCase()}
function renderPendingFiles(){const list=$("#attachmentList");list.replaceChildren();pendingFiles.forEach((file,index)=>{const item=document.createElement("div");item.className="attachment-chip";if(file.kind==="image"){const preview=document.createElement("img");preview.className="attachment-thumb";preview.src=file.dataUrl;preview.alt="Photo attachment preview";item.append(preview)}const name=document.createElement("span");name.textContent=(file.kind==="image"?"Photo · ":"File · ")+file.name;const remove=document.createElement("button");remove.type="button";remove.textContent="×";remove.setAttribute("aria-label","Remove "+file.name);remove.addEventListener("click",()=>{pendingFiles.splice(index,1);renderPendingFiles()});item.append(name,remove);list.append(item)})}
async function imageToDataUrl(file){if(file.type==="image/gif"){if(file.size>4.7*1024*1024)throw new Error("GIF is too large to send. Choose a smaller image.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}if(typeof createImageBitmap!=="function"){if(file.size>4.7*1024*1024)throw new Error("This browser can't compress this large photo. Try a smaller image or Chrome.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext("2d");ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/jpeg",.84));if(!blob)throw new Error("Could not prepare this photo.");if(blob.size>4.7*1024*1024){const scale2=Math.sqrt((4.7*1024*1024)/blob.size)*.92;const smaller=document.createElement("canvas");smaller.width=Math.max(1,Math.round(canvas.width*scale2));smaller.height=Math.max(1,Math.round(canvas.height*scale2));smaller.getContext("2d").drawImage(canvas,0,0,smaller.width,smaller.height);blob=await new Promise(resolve=>smaller.toBlob(resolve,"image/jpeg",.76))}if(!blob||blob.size>4.7*1024*1024)throw new Error("This photo is still too large. Try a smaller picture.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}
async function readSelectedFiles(fileList){let added=0;for(const file of Array.from(fileList||[])){try{if(file.type.startsWith("image/")){if(file.size>15*1024*1024){showToast(file.name+" is over the 15 MB photo limit.");continue}const dataUrl=await imageToDataUrl(file);pendingFiles.push({name:file.name||"camera-photo.jpg",mimeType:dataUrl.startsWith("data:image/png")?"image/png":dataUrl.startsWith("data:image/gif")?"image/gif":"image/jpeg",kind:"image",dataUrl});added++}else if(file.size>MAX_FILE_BYTES){showToast(file.name+" is over the 5 MB file limit.");continue}else if(TEXT_EXTENSIONS.has(fileExtension(file.name))){const content=await file.text();pendingFiles.push({name:file.name,mimeType:file.type||"text/plain",kind:"text",content:content.slice(0,30000)});added++}else if(fileExtension(file.name)==="pdf"){if(!window.pdfjsLib){showToast("PDF reader did not load. Try a TXT version.");continue}const pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let pages=[];for(let pageNo=1;pageNo<=Math.min(pdf.numPages,20);pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();pages.push(content.items.map(item=>item.str).join(" "))}pendingFiles.push({name:file.name,mimeType:"application/pdf",kind:"text",content:pages.join("\n\n").slice(0,30000)});added++}else showToast("That file type isn't supported yet: "+file.name)}catch(error){showToast(error.message||("Couldn't read "+file.name))}}renderPendingFiles();return added}

