async function sendMessage(text){const value=String(text||"").trim();if((!value&&!pendingFiles.length)||busy)return;if(!currentChat())makeChat();const files=pendingFiles.splice(0);const fileSummary=files.map(f=>`[Attached ${f.kind}: ${f.name}]`).join(" ");appendMessage("user",[value,fileSummary].filter(Boolean).join("\n"));input.value="";input.style.height="auto";renderPendingFiles();setBusy(true);await askMiniAI(files)}
