window.handleMiniAIBack = function(){
  const settings = document.querySelector("#settingsModal");
  if (settings && !settings.hidden) { closeSettings(); return true; }
  const sidebar = document.querySelector("#sidebar");
  if (sidebar && sidebar.classList.contains("open")) { closeSidebar(); return true; }
  const searchWrap = document.querySelector("#historySearchWrap");
  if (searchWrap && searchWrap.classList.contains("visible")) { searchWrap.classList.remove("visible"); const field=document.querySelector("#historySearch"); if(field)field.value=""; renderHistory(); return true; }
  const attachMenu = document.querySelector("#attachMenu");
  if (attachMenu && !attachMenu.hidden && attachMenu.classList.contains("open")) { attachMenu.classList.remove("open"); return true; }
  return false;
};

