function speakReply(text){
 if((!voiceCallActive&&!prefs.autoSpeak)||!text)return;
 const synth=window.speechSynthesis;
 if(!synth||typeof SpeechSynthesisUtterance==="undefined"){voiceStatus.textContent="Voice playback is unavailable in this browser. Open MiniAI in Chrome.";return}
 if(callRecognition){try{callRecognition.stop()}catch{}callRecognition=null}
 voiceSpeaking=true;
 synth.cancel();
 synth.resume();
 const clean=String(text).replace(/```[\s\S]*?```/g,"Code block omitted from speech.").replace(/https?:\/\/\S+/g,"link").replace(/[#*_>`]/g,"").replace(/\s+/g," ").trim().slice(0,5000);
 if(!clean){voiceSpeaking=false;startCallListening();return}
 const chunks=[];let rest=clean;
 while(rest.length>220){let cut=Math.max(rest.lastIndexOf(". ",220),rest.lastIndexOf("? ",220),rest.lastIndexOf("! ",220),rest.lastIndexOf(", ",220),rest.lastIndexOf(" ",220));if(cut<100)cut=220;else if(/[.?!]/.test(rest[cut]))cut++;chunks.push(rest.slice(0,cut).trim());rest=rest.slice(cut).trim()}
 if(rest)chunks.push(rest);
 let index=0;const voices=synth.getVoices();const english=voices.filter(v=>/^en([-_]|$)/i.test(v.lang));
 const voice=voices.find(v=>v.voiceURI===prefs.voiceURI)||english.find(v=>/Google US English|Microsoft.*(Aria|Jenny|Guy)|Samantha|Daniel/i.test(v.name))||english.find(v=>/^en-US/i.test(v.lang))||english[0]||voices[0]||null;
 const finish=()=>{voiceSpeaking=false;voiceOrb?.classList.remove("active");if(voiceCallActive){voiceStatus.textContent="Listening…";setTimeout(startCallListening,250)}};
 const speakNext=()=>{if(!voiceCallActive&&!prefs.autoSpeak){finish();return}if(index>=chunks.length){finish();return}
  const u=new SpeechSynthesisUtterance(chunks[index++]);u.lang=voice?.lang||(/^[a-z]{2}([-_]|$)/i.test(navigator.language||"")?(navigator.language):"en-US");if(voice)u.voice=voice;u.rate=Number(prefs.speechRate)||1;u.pitch=Number(prefs.speechPitch)||1;u.volume=Number(prefs.speechVolume)||1;
  u.onstart=()=>{voiceStatus.textContent="MiniAI is speaking…";voiceOrb?.classList.add("active")};
  u.onend=()=>{if(index<chunks.length){synth.resume();speakNext()}else finish()};
  u.onerror=e=>{console.warn("MiniAI speech playback error:",e.error);finish();voiceStatus.textContent="Couldn't play the voice reply. Check your phone's text-to-speech settings."};
  synth.speak(u);synth.resume();
 };
 speakNext();
}
function startCallListening(){if(!voiceCallActive||busy||voiceSpeaking||window.speechSynthesis?.speaking)return;if(!SpeechRecognition){voiceStatus.textContent="Voice input needs Chrome on Android or a supported browser.";return}if(callRecognition){try{callRecognition.stop()}catch{}callRecognition=null}const r=makeRecognition();if(!r)return;callRecognition=r;r.onstart=()=>{voiceStatus.textContent="Listening…";voiceOrb.classList.add("active")};r.onresult=e=>{let text="";for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)text+=e.results[i][0].transcript+" ";if(text.trim()){voiceTranscript.textContent="You: "+text.trim();voiceStatus.textContent="Thinking…";voiceOrb.classList.remove("active");try{r.stop()}catch{}callRecognition=null;sendMessage(text.trim())}};r.onerror=e=>{voiceOrb.classList.remove("active");if(e.error==="not-allowed"){voiceStatus.textContent="Microphone permission was denied.";endVoiceCall()}else if(voiceCallActive){voiceStatus.textContent="Reconnecting microphone…";setTimeout(startCallListening,900)}};r.onend=()=>{voiceOrb.classList.remove("active");if(voiceCallActive&&!busy&&!window.speechSynthesis?.speaking){callRecognition=null;setTimeout(startCallListening,350)}};try{r.start()}catch{voiceStatus.textContent="Could not start microphone. Try again."}}
function beginVoiceCall(){if(!SpeechRecognition){showToast("For voice calls, open MiniAI in Chrome and allow microphone access.");return}voiceCallActive=true;voiceCall.hidden=false;voiceEnd.textContent="End call";voiceStatus.textContent="Starting microphone…";voiceTranscript.textContent="Speak naturally. MiniAI will answer aloud.";startCallListening()}
function endVoiceCall(){voiceCallActive=false;if(callRecognition){try{callRecognition.stop()}catch{}callRecognition=null}if(dictationRecognition){try{dictationRecognition.stop()}catch{}dictationRecognition=null}window.speechSynthesis?.cancel();voiceOrb.classList.remove("active");voiceCall.hidden=true;voiceChatButton.classList.remove("listening")}
bindSettings();
